:[{"label":"Teilnahmegebühr","amount":69,"currency":"EUR"},{"label":"U18","amount":39,"currency":"EUR"}]},"routes":{"sourceUrl":"https://www.datasport.de/anmeldeservice/ostalbgravel2027","quote":"Kurzstrecke 55 km | ca. 800 hm; Langstrecke 83 km | 1.400 hm","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":[{"name":"Kurzstrecke","distanceKm":55,"elevationM":800},{"name":"Langstrecke","distanceKm":83,"elevationM":1400}]}}$lr$::jsonb,updated_at=now(),last_seen_at=now() where id=v;
