do $do$ declare v uuid:='d57834f6-a747-4237-9507-c7e3a41c63bc'; c jsonb:=$lr$[{"n":"Fun Race 20 km","k":20,"u":800},{"n":"Trophy Race 40 km","k":40,"u":1600},{"n":"Adventure Race cca 100 km (MTB nebo gravel, GPS)","k":100,"u":1800},{"n":"Kids U7 Laufrad","b":6,"g":"kids"},{"n":"Kids U7","b":6,"g":"kids"},{"n":"Kids U9","a":7,"b":8,"g":"kids"},{"n":"Kids U11","a":9,"b":10,"g":"kids"},{"n":"Youth U13","a":11,"b":12,"g":"youth"},{"n":"Youth U15","a":13,"b":14,"g":"youth"}]$lr$; s jsonb:=$lr$[{"u":"https://www.dirndltal-race.at/","k":"official","q":"18. September 2027. Das DTR ist Teil der MTB Trophy, niederösterreichs größter MTB Rennserie.","f":["start_date","series_id","website_url"]},{"u":"https://www.dirndltal-race.at/funundtrophyrace","k":"official","q":"Am Samstag, den 18. September 2027 ... im Rahmen der Top-Six MTB-Trophy. Trophy Race ca. 40km und ca. 1.600hm; Fun Race ca. 20km und ca. 800hm","f":["series_id","categories"]},{"u":"https://www.dirndltal-race.at/adventurerace","k":"official","q":"18 September 2027 / St. Pölten - Frankenfels. Distanz: rund 100km / Änderungen vorbehalten. Höhenmeter: rund 1.800 hm","f":["categories","disciplines"]},{"u":"https://www.dirndltal-race.at/kids-und-youth-race","k":"official","q":"Kids Race und Youth Race 2027. Rennen 1: U7 Laufrad; U7; U11 und U9; U15 und U13","f":["categories","age_categories"]}]$lr$; l text[]:=array[$lr$website_url$lr$,$lr$categories$lr$,$lr$age_categories$lr$,$lr$age_confidence$lr$,$lr$audience$lr$,$lr$series_id$lr$]::text[]; r jsonb; begin
