update events set website_url=$lr$https://www.dirndltal-race.at/$lr$,registration_url=null,disciplines=array[$lr$mtb$lr$,$lr$xcm$lr$,$lr$gravel$lr$]::text[],formats=array[$lr$xcm$lr$]::text[],audience=$lr$mixed$lr$,age_categories=array[$lr$u7$lr$,$lr$u9$lr$,$lr$u11$lr$,$lr$u13$lr$,$lr$u15$lr$,$lr$u17$lr$,$lr$amateur$lr$]::text[],age_confidence=$lr$explicit$lr$,source_kind=$lr$official$lr$,series_id=$lr$44322b75-313d-4723-9ff0-8abab96b376d$lr$::uuid,description=$lr$MTB a gravel v Laubenbachmühle u Frankenfelsu, kolo seriálu TopSix MTB Trophy. Fun Race, Trophy Race, Adventure Race ze St. Pöltenu s vlastní navigací podle GPS a dětské závody U7 až U15. Přímou přihlášku pro rok 2027 jsme zatím neověřili.$lr$,practical_details=$lr${"venue":{"sourceUrl":"https://www.dirndltal-race.at/funundtrophyrace","quote":"Start und Ziel direkt bei Betriebszentrum Laubenbachmühle ( Bahnhof der Mariazellerbahn ) in 3213 Frankenfels, Laubenbachgegend.","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":{"name":"Bahnhof Laubenbachmühle","postalCode":"3213","locality":"Frankenfels","countryCode":"AT","precision":"start"}},"organizer":{"sourceUrl":"https://www.dirndltal-race.at/","quote":"Veranstalter ARBÖ RC Purgstall, Fasangartengasse 9, 3251 Purgstall","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":{"name":"ARBÖ RC Purgstall","url":"https://www.rcpurgstall.at/"}},"schedule":{"sourceUrl":"https://www.dirndltal-race.at/kids-und-youth-race","quote":"Rennen 1: 09:30 Uhr - U7 Laufrad; Fun und Trophy Race ab 13:30 Uhr; Neutraler Start St. Pölten ab circa 10:00 Uhr","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":[{"sourceQuote":"Rennen 1: 09:30 Uhr - U7 Laufrad","sourceUrl":"https://www.dirndltal-race.at/kids-und-youth-race","label":"Kids und Youth Race","date":"2027-09-18","time":"09:30","timeZone":"Europe/Vienna"},{"sourceQuote":"St. Pölten Rathausplatz, ab circa 10:00 Uhr im Minutentakt","sourceUrl":"https://www.dirndltal-race.at/adventurerace","approximate":true,"label":"Adventure Race, St. Pölten","date":"2027-09-18","time":"10:00","timeZone":"Europe/Vienna"},{"sourceQuote":"Fun und Trophy Race ab 13:30 Uhr","sourceUrl":"https://www.dirndltal-race.at/funundtrophyrace","label":"Fun und Trophy Race","date":"2027-09-18","time":"13:30","timeZone":"Europe/Vienna"}]},"fees":{"sourceUrl":"https://www.dirndltal-race.at/kids-und-youth-race","quote":"U7 bis U11 = kostenlos (freiwillige Spende); U13 bis U15 laut ÖRV = 11 Euro","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":[{"sourceQuote":"U7 bis U11 = kostenlos (freiwillige Spende)","sourceUrl":"https://www.dirndltal-race.at/kids-und-youth-race","label":"Kids U7 bis U11","amount":0,"currency":"EUR"},{"sourceQuote":"U13 bis U15 laut ÖRV = 11 Euro","sourceUrl":"https://www.dirndltal-race.at/kids-und-youth-race","label":"Youth U13 bis U15","amount":11,"currency":"EUR"},{"sourceQuote":"Fun Race : € 45,- (ab 16.09.2027 + € 10,- Nachnenngebühr","sourceUrl":"https://www.dirndltal-race.at/funundtrophyrace","label":"Fun Race","amount":45,"currency":"EUR"},{"sourceQuote":"Fun Race für Jugend (2009-2012): € 40,-","sourceUrl":"https://www.dirndltal-race.at/funundtrophyrace","label":"Fun Race Jugend (2009-2012)","amount":40,"currency":"EUR"},{"sourceQuote":"Startgebühr bis 10.9.2027 € 88,-","sourceUrl":"https://www.dirndltal-race.at/adventurerace","label":"Adventure Race","amount":88,"currency":"EUR"}]},"routes":{"sourceUrl":"https://www.dirndltal-race.at/","quote":"Fun Race 20km und 800hm; Trophy Race 40km 1600hm; Adventure Race rund 100 km und 1.800hm","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":[{"name":"Fun Race","distanceKm":20,"elevationM":800},{"name":"Trophy Race","distanceKm":40,"elevationM":1600},{"name":"Adventure Race (Richtwert)","distanceKm":100,"elevationM":1800,"surface":"MTB oder Gravel"}]}}$lr$::jsonb,updated_at=no