update events set event_type=$lr$race$lr$,registration_url=null,source_kind=$lr$official$lr$,description=$lr$Gravel v jižním Vídeňském lese s měřenými úseky, jejichž časy tvoří výsledkové pořadí. Krátká trasa má přibližně 50 km a 3 úseky, dlouhá přibližně 85 až 92 km a 6 úseků; zdroje se v délce liší a trasy pro rok 2027 pořadatel zatím výslovně nepotvrdil. Přihlášky na rok 2027 zatím nejsou otevřené.$lr$,practical_details=$lr${"venue":{"sourceUrl":"https://goodtimesgravel.at/","quote":"This is the event location – Freizeitgelände, Maria Enzersdorf","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"year_neutral","value":{"name":"Freizeitgelände","postalCode":"2344","locality":"Maria Enzersdorf","countryCode":"AT","precision":"venue"}},"organizer":{"sourceUrl":"https://bikeboard.at/termine/good-times-gravel-termin16408","quote":"Ort 2344 Maria Enzersdorf, Niederösterreich. Veranstalter BikeSchneiderei e.U.","checkedAt":"2026-11-04T21:30:00+01:00","editionYear":2027,"status":"current","value":{"name":"BikeSchneiderei e.U.","url":"https://goodtimesgravel.at/"}}}$lr$::jsonb,updated_at=now(),last_seen_at=now() where id=v;
