insert into event_overrides(event_id,fields,locked_fields,updated_by) select v,(select jsonb_object_agg(lk,case when lk='categories' then (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',y.n,'distanceKm',y.k,'ageMin',y.a,'ageMax',y.b))) from jsonb_to_recordset(c) y(n text,k float8,a int,b int)) else coalesce(r->lk,'null'::jsonb) end) from unnest(l) lk),l,'owner wishlist 2027 review 2026-11-04' on conflict(event_id) do update set fields=event_overrides.fields||excluded.fields,locked_fields=array(select distinct q from unnest(event_overrides.locked_fields||excluded.locked_fields) q),updated_by=excluded.updated_by,updated_at=now();
insert into watched_urls(url,kind,added_by,notes) select w,'race','owner-wishlist-2026-11-04','Organiser page for the 2027 edition; reviewed by hand' from unnest(array[$lr$https://www.stupavskymaraton.sk/inpage/mtb-sprint-biely-kriz-2024/$lr$]::text[]) w on conflict(url) do nothing;
end $do$;
